Let the initial data of the KPZ fixed point $\mathfrak{h}_0$ satisfy Assumption~1.1.

Then, for any $T > 0$ and $A\geq 0$,
\begin{equation}
\mathbb P_{\mathfrak{h}_0}\Bigl(\dim(\mathcal{T}_{T,A}(\mathfrak{h})) \leq \tfrac{2}{3}\Bigr) \, = \, 1.
\end{equation}

For any initial data $\mathfrak{h}_0$ satisfying Assumption~1.1(a) and for any $T > 0$, there exists a random variable $\mathcal{B} \in \mathbb{R}$, which is almost surely finite, such that the KPZ fixed point $\mathfrak{h}_{t}$ satisfies

\begin{equation}
  \mathfrak{h}_t(x) \leq \mathcal{B} - \frac{1}{8}\min\left(\sqrt{2}\gamma, \frac{1}{t}\right) |x|^{1/2},
\end{equation}

for all $x \in \mathbb{R}$ and $t \in [0, T]$, where the constant $\gamma > 0$ is from Assumption~1.1. In particular, for every fixed $t \geq 0$, the KPZ fixed point $\mathfrak{h}_t(x)$ is almost surely bounded  above, and $\lim_{x \to \pm \infty} \mathfrak{h}_t(x) = -\infty$ almost surely.

Let the initial data of the KPZ fixed point satisfy Assumption~1.1(a). For  $\delta \in (0, \frac{1}{3})$, $T >T_0> 0$ and $L > 0$, one has

\begin{equation}
|\mathrm{Max}(\mathfrak{h}^L_{t}) - \mathrm{Max}(\mathfrak{h}_{s}^L)|\leq \mathcal{C} |t-s|^{\frac{1}{3} - \delta},
\end{equation}

for all $s \neq t \in [T_0,T]$, where the random variable $\mathcal{C}$ is almost surely finite.

Let the initial data $\mathfrak{h}_0 \in \text{\upshape{UC}}$ of the KPZ fixed point satisfy $\mathfrak{h}_0(x) \leq \alpha$ for some $\alpha \in \mathbb{R}$ and for any $x \in \mathbb{R}$. 
Then, for any $0 < L \leq \bar L$, $A > 0$ and $0 < T_0 < T$, 
\begin{equation}
\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \mathsf{TP}_{\!\!A, \bar L}^{\varepsilon}\Bigr) \leq C \varepsilon t^{-\frac{1}{3}},
\end{equation}
for $t \in [T_0, T]$ and $\varepsilon \in (0,1)$, and for a constant $C \geq 0$ depending on $T_0$, $\bar L$, $A$, $\beta$ (which comes into the definition (12)) and $\alpha$ (i.e., the dependence on $\mathfrak{h}_0$ is merely via the constant $\alpha$).

Let the initial state $\mathfrak{h}_0$ of the KPZ fixed point satisfy Assumption~1.1, and suppose that $A>0$ and $t>0$. There exist $L_0$ and $c' > 0$ (both depending on $A$, $t$, and $\mathfrak{h}_0$) such that, for all $L\geq L_0$ and $\varepsilon \in (0,1)$,


    \begin{equation}
        \mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}_t \in \mathsf{TP}_{\!\!A, L}^{\varepsilon}\Bigr) \geq c' \varepsilon.
    \end{equation}

    Further, $c'$ and $L_0$ can be taken to depend on $t>0$ in a continuous manner.

For $\eta_i = (\varepsilon_i, \delta_i)$ with positive components, define $|\eta_i| = \varepsilon_i \delta_i > 0$. Assume that the initial data of the KPZ fixed point satisfies $\mathfrak{h}_0(x) \leq \alpha$ for some $\alpha\in \mathbb{R}$ and for all $x \in \mathbb{R}$. For every fixed $t > 0$, $L > 0$ and $A > 0$ the  following  limits exist:
\begin{subequations}
\begin{align}
	\mathcal{F}^{(\eta_1; \star)}_{t, M, L}(x_1, x_2) &:= \underset{\eta_2 \searrow 0}{\widetilde{\mathrm{lim}}} \frac{1}{|\eta_2|} \mathcal{F}^{(\eta_1; \eta_2)}_{t, M, L}(x_1, x_2),\\
	\mathcal{F}_{t, M, L}(x_1, x_2) &:= \underset{\eta_1 \searrow 0}{\widetilde{\mathrm{lim}}} \frac{1}{|\eta_1|} \mathcal{F}^{(\eta_1; \star)}_{t, M, L}(x_1, x_2),
\end{align}
\end{subequations}
uniformly over $x_1, x_2 \in \mathsf{J}_{L}$, such that $x_2 - x_1 \geq A$, and locally uniformly over $M \in \mathbb{R}$; the limit (4a) holds uniformly over $\eta_1 \in (0, \frac{A}{2}]^2$, i.e., for $\varepsilon_1$ and $\delta_1$ in $(0, \frac{A}{2}]$.

Furthermore, the following limit holds pointwise 
\begin{equation}
\mathcal{F}_{1, M}(x_1, x_2) := \lim_{L \to \infty} \mathcal{F}_{1, M, L}(x_1, x_2).
\end{equation}

The function $\mathcal{F}_{t, M, L}(x_1, x_2)$ is continuous in $M \in \mathbb{R}$ and $x_1, x_2 \in \mathsf{J}_{L}$ such that $x_1 < x_2$, and satisfies the scaling identity
\begin{equation}
\mathcal{F}_{t, M, L}(x_1, x_2) = t^{-2} \mathcal{F}_{1, t^{-1/3} M, t^{-2/3} L} \bigl(t^{-\frac{2}{3}} x_1, t^{-\frac{2}{3}} x_2\bigr),
\end{equation}
where the right-hand function is defined by (4b) with the initial data $\mathfrak{h}_0^{(t)}(x) := t^{-1/3}\mathfrak{h}_0(t^{2/3} x)$.

Finally, for any $\bar L > 0$, there exists a constant $C \geq 0$, depending on $L$, $\bar L$ and $\alpha$, such that 
\begin{equation}
\mathcal{F}_{1, M, L}(x_1, x_2) \leq C |x_2 - x_1|^{-\frac{3}{2}},
\end{equation}
for any  $x_1, x_2 \in \mathsf{J}_L$ such that $x_1 < x_2$, and any $|M| \leq \bar L$.

For any $\delta > 0$,
\begin{align}
\Bigl|\mathcal{L}(y, s; x, t) + \tfrac{(y - x)^2}{t-s}\Bigr| \leq \mathcal{C}_\delta \bigl(1 + \Vert y, s, x, t \Vert^{\frac{1}{5}}\bigr) (t-s)^{\frac{1}{3} - \delta},
\end{align}
for all $(y, s; x, t) \in \mathbb{R}^4_{\uparrow}$. Here, $\Vert \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{.5}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5} \Vert$ denotes the $\ell_1$-norm on $\mathbb{R}^4$;  $\mathcal{C}_\delta$ is a random variable, which depends on $\delta$ but is independent of $(y, s, x, t)$ and satisfies $\mathbb P (\mathcal{C}_\delta > m) \leq a \exp(-c m^{3/2})$ for any $m \geq 0$ and for some positive $\delta$-dependent constants $a$ and $c$. In particular, $\mathcal{C}_\delta$ is almost surely finite.

Let the initial state $\mathfrak{h}_0$ of the KPZ fixed point satisfy Assumption~1.1, and suppose that $A>0$ and $t>0$. There exist $L_0$ and $c' > 0$ (both depending on $A$, $t$, and $\mathfrak{h}_0$) such that, for all $L\geq L_0$ and $\varepsilon \in (0,1)$,


    \begin{equation}
        \mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}_t \in \mathsf{TP}_{\!\!A, L}^{\varepsilon}\Bigr) \geq c' \varepsilon.
    \end{equation}

    Further, $c'$ and $L_0$ can be taken to depend on $t>0$ in a continuous manner.

There exist $\mathscr{F}$-measurable random variables $\mathrm{Corner}^{\downarrow}$ and $\mathrm{Corner}^{\uparrow}$ such that the following holds. Conditionally on $\mathscr{F}$, and on the $\mathscr{F}$-measurable event that $x_0+A+2 \leq n^{1/60}$, the distribution of $Z$ is a normal random variable with mean $\frac{1}{2}(\mathcal{P}_{n,1}(x_0+A) + \mathcal{P}_{n,1}(x_0+A+2))$ and variance one, conditional on lying inside $[\mathrm{Corner}^{\downarrow}, \mathrm{Corner}^{\uparrow}]$. Further, when $z=\mathrm{Corner}^{\uparrow}$,

\begin{equation}
\sup_{x\in [x_0+A,x_0+A+2]} \mathfrak{h}^{{\scriptscriptstyle(}n{\scriptscriptstyle)},z}(x) = \mathfrak{h}^{{\scriptscriptstyle(}n{\scriptscriptstyle)}}(x_0).
\end{equation}
